// Alegra devuelve máximo 30 facturas por llamada, así que el nodo anterior
// hace varias llamadas y entrega una página por cada una.
// Aquí las abrimos para quedar con una factura por item.

const facturas = [];

for (const item of items) {
  const cuerpo = item.json;
  if (Array.isArray(cuerpo)) {
    facturas.push(...cuerpo);
  } else if (Array.isArray(cuerpo.data)) {
    facturas.push(...cuerpo.data);
  } else {
    facturas.push(cuerpo);
  }
}

return facturas.map((factura) => ({ json: factura }));

// ─── Puedes cambiar esto ──────────────────────────────────────────────
const MONEDA = 'COP';           // solo afecta cómo se ve la plata en el correo
const MINIMO_PARA_COBRAR = 0;   // no escribas por deudas menores a este monto
// ──────────────────────────────────────────────────────────────────────

const hoy = new Date();
hoy.setHours(0, 0, 0, 0);

const plata = (n) =>
  new Intl.NumberFormat('es-CO', {
    style: 'currency',
    currency: MONEDA,
    maximumFractionDigits: 0,
  }).format(n);

// El nombre del cliente llega distinto según el país. Lo normalizamos.
const nombreDe = (cliente) => {
  const n = cliente && cliente.name;
  if (Array.isArray(n)) return n.filter(Boolean).join(' ');
  if (n && typeof n === 'object') return [n.firstName, n.lastName].filter(Boolean).join(' ');
  return n || 'Cliente sin nombre';
};

const numeroDe = (f) =>
  String((f.numberTemplate && f.numberTemplate.fullNumber) || f.number || f.id);

const porCliente = new Map();

for (const item of items) {
  const f = item.json;

  // El saldo pendiente viene en 'balance'. Si esa cuenta no lo trae,
  // lo deducimos del total menos lo ya pagado.
  const saldo = Number(
    f.balance ?? Number(f.total ?? 0) - Number(f.totalPaid ?? 0)
  );
  if (!(saldo > 0)) continue;
  if (!f.dueDate) continue;

  const vence = new Date(f.dueDate + 'T00:00:00');
  const mora = Math.floor((hoy - vence) / 86400000);
  if (mora <= 0) continue;

  const cliente = f.client || {};
  const clienteId = cliente.id;
  // Sin id de cliente no podemos ir a buscar su correo. La saltamos.
  if (!clienteId) continue;

  const clave = String(clienteId);

  if (!porCliente.has(clave)) {
    porCliente.set(clave, {
      clienteId: clave,
      cliente: nombreDe(cliente),
      totalVencido: 0,
      cantidad: 0,
      diasMoraMax: 0,
      facturas: [],
    });
  }

  const c = porCliente.get(clave);
  c.totalVencido += saldo;
  c.cantidad += 1;
  if (mora > c.diasMoraMax) c.diasMoraMax = mora;
  c.facturas.push({
    numero: numeroDe(f),
    saldo: Math.round(saldo),
    saldoTexto: plata(saldo),
    vence: f.dueDate,
    mora,
  });
}

const salida = [...porCliente.values()]
  .filter((c) => c.totalVencido >= MINIMO_PARA_COBRAR)
  .map((c) => ({
    ...c,
    totalVencido: Math.round(c.totalVencido),
    totalTexto: plata(c.totalVencido),
    // La más vieja primero: es la que más pesa en la conversación.
    facturas: c.facturas.sort((a, b) => b.mora - a.mora),
  }))
  .sort((a, b) => b.totalVencido - a.totalVencido);

return salida.map((c) => ({ json: c }));

// ─── Puedes cambiar esto ──────────────────────────────────────────────
const REMITENTE = 'REEMPLAZAR_NOMBRE_DE_TU_EMPRESA';
// ──────────────────────────────────────────────────────────────────────

// El nodo anterior pidió un contacto por cada cliente y devuelve las
// respuestas en el mismo orden. Por eso emparejamos por posición.
const agrupado = $('Agrupar vencidas por cliente').all();

const salida = items.map((item, i) => {
  const contacto = item.json || {};
  const datos = agrupado[i].json;

  // El correo llega como texto, como lista o dentro de un objeto,
  // según el país y cómo se haya cargado el contacto.
  let correo = contacto.email;
  if (Array.isArray(correo)) correo = correo[0];
  if (correo && typeof correo === 'object') correo = correo.email;
  correo = typeof correo === 'string' ? correo.trim() : '';

  const plural =
    datos.cantidad === 1
      ? 'una factura pendiente'
      : datos.cantidad + ' facturas pendientes';

  const filas = datos.facturas
    .map(
      (f) =>
        '<tr>' +
        '<td style="padding:6px 16px 6px 0;">' + f.numero + '</td>' +
        '<td style="padding:6px 16px 6px 0;text-align:right;white-space:nowrap;">' + f.saldoTexto + '</td>' +
        '<td style="padding:6px 0;color:#555;">venció el ' + f.vence + ' (' + f.mora + ' días)</td>' +
        '</tr>'
    )
    .join('');

  const mensaje = [
    '<div style="font-family:Arial,Helvetica,sans-serif;font-size:15px;color:#222;line-height:1.5;">',
    '<p>Hola, ' + datos.cliente + ':</p>',
    '<p>Te escribimos para recordarte que tienes ' + plural + ' con nosotros, por un total de <strong>' + datos.totalTexto + '</strong>.</p>',
    '<table style="border-collapse:collapse;margin:16px 0;">' + filas + '</table>',
    '<p>Si ya hiciste el pago, cuéntanos y lo cruzamos de una vez.</p>',
    '<p>Si necesitas otra fecha o armar un acuerdo, escríbenos y lo miramos juntos.</p>',
    '<p>Gracias por tu confianza.<br>' + REMITENTE + '</p>',
    '</div>',
  ].join('');

  const asunto =
    datos.cantidad === 1
      ? 'Recordatorio de pago — factura ' + datos.facturas[0].numero
      : 'Recordatorio de pago — ' + datos.cantidad + ' facturas pendientes';

  return {
    json: {
      cliente: datos.cliente,
      clienteId: datos.clienteId,
      correo,
      tieneCorreo: correo.length > 0,
      asunto,
      mensaje,
      totalVencido: datos.totalVencido,
      totalTexto: datos.totalTexto,
      cantidad: datos.cantidad,
      diasMoraMax: datos.diasMoraMax,
    },
  };
});

return salida;
